package com.example.e2e.coupon;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names of com.example.e2e.coupon, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class CouponMetrics {
    private CouponMetrics() {
    }

    /** outcome="failed" on the timer already running (same thread). */
    public static void tagFailed() {
        Outcomes.tag("failed");
    }

    /** coupons{outcome="updated"} +1; rows is one sample of the distribution coupons.rows{outcome="updated"}. */
    public static void couponsUpdated(Number rows) {
        Outcomes.record("coupons", "updated", "rows", rows);
    }

    /** coupon.usage{outcome="saved"} +1; coupon.usage.uses{outcome="saved"} grows by uses. */
    public static void couponUsageSaved(Number uses) {
        Outcomes.count("coupon.usage", "saved", "uses", uses);
    }

    /** coupon{outcome="sent"} +1. */
    public static void couponSent() {
        Outcomes.count("coupon", "sent");
    }

    /** coupon.resend{outcome="failed"} +1. */
    public static void couponResendFailed() {
        Outcomes.count("coupon.resend", "failed");
    }

    /** coupon{outcome="published"} +1. */
    public static void couponPublished() {
        Outcomes.count("coupon", "published");
    }

    /** coupon.redemption{outcome="completed"} +1. */
    public static void couponRedemptionCompleted() {
        Outcomes.count("coupon.redemption", "completed");
    }
}
